import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.B5WAEDB7.js";const c=JSON.parse('{"title":"Durchlaufhistorie","description":"Vergangene Flow-Ausführungen einsehen und Fehler nachvollziehen.","frontmatter":{"title":"Durchlaufhistorie","description":"Vergangene Flow-Ausführungen einsehen und Fehler nachvollziehen."},"headers":[],"relativePath":"flows/durchlaufhistorie.md","filePath":"flows/durchlaufhistorie.md","lastUpdated":1786518403000}'),s={name:"flows/durchlaufhistorie.md"};function a(l,e,h,d,o,u){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="durchlaufhistorie" tabindex="-1">Durchlaufhistorie <a class="header-anchor" href="#durchlaufhistorie" aria-label="Permalink to &quot;Durchlaufhistorie&quot;">​</a></h1><p>Jede Ausführung eines Flows heißt <strong>Ausführung</strong>. Der Reiter <strong>Verlauf</strong> im Flow zeigt die vergangenen.</p><h2 id="die-liste" tabindex="-1">Die Liste <a class="header-anchor" href="#die-liste" aria-label="Permalink to &quot;Die Liste&quot;">​</a></h2><p>Überschrift: <strong>Vorherige Ausführungen</strong>.</p><table tabindex="0"><thead><tr><th>Spalte</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Startzeit</strong></td><td>Wann die Ausführung begann</td></tr><tr><td><strong>Seit Start</strong></td><td>Vergangene Zeit, relativ</td></tr><tr><td><strong>Dauer</strong></td><td>Wie lange sie lief</td></tr><tr><td><strong>Schritte</strong></td><td>Anzahl ausgeführter Schritte</td></tr><tr><td><strong>Status</strong></td><td>Ergebnis</td></tr></tbody></table><p>Über <strong>Öffnen</strong> sehen Sie eine Ausführung im Detail, über <strong>Aktualisieren</strong> laden Sie die Liste neu.</p><p>Zeitangaben erscheinen relativ: <em>Gerade eben</em>, <em>vor {n} Minuten</em>, <em>vor {n} Stunden</em>, <em>vor {n} Tagen</em>. Ist kein Zeitpunkt bekannt: <em>Datum unbekannt</em>.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Fertig</strong> / <strong>Abgeschlossen</strong></td><td>Vollständig durchgelaufen</td></tr><tr><td><strong>Fehler</strong> / <strong>Fehlgeschlagen</strong></td><td>Abgebrochen</td></tr><tr><td><strong>In Bearbeitung</strong></td><td>Läuft gerade</td></tr><tr><td><strong>Wartet</strong></td><td>Wartet auf ein Ereignis</td></tr><tr><td><strong>Erstellt</strong></td><td>Angelegt, noch nicht gestartet</td></tr><tr><td><strong>Testausführung</strong></td><td>Ein Testlauf, kein echter Durchlauf</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">„Wartet&quot; ist meist kein Problem</p><p>Dieser Status tritt planmäßig auf, wenn ein Flow auf etwas wartet — auf eine <a href="/flows/seiten-in-flows">Seite</a>, die noch niemand abgesendet hat, oder auf das Ende eines <strong>Warten</strong>-Schritts.</p><p>Stapeln sich allerdings wartende Ausführungen, prüfen Sie, ob die zugehörigen Links tatsächlich bei den richtigen Personen angekommen sind.</p></div><h2 id="eine-ausfuhrung-ansehen" tabindex="-1">Eine Ausführung ansehen <a class="header-anchor" href="#eine-ausfuhrung-ansehen" aria-label="Permalink to &quot;Eine Ausführung ansehen&quot;">​</a></h2><p>Beim Öffnen zeigt der Editor die Daten dieses Laufs statt des leeren Bauplans:</p><blockquote><p><strong>Anzeige vorheriger Ausführungen</strong></p><p><em>Dies sind Daten eines vorherigen Flow-Ausführungen. Sie wurden automatisch geladen, um Ihnen das Verhalten des Flows zu verdeutlichen.</em></p></blockquote><p>Angezeigt werden <strong>Ausgeführt am</strong>, <strong>Geladen am</strong>, <strong>Status</strong> und <strong>Schritte</strong>.</p><table tabindex="0"><thead><tr><th>Aktion</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Andere auswählen</strong></td><td>Wechselt zu einer anderen Ausführung</td></tr><tr><td><strong>Entfernen</strong></td><td>Verlässt die Datenansicht</td></tr></tbody></table><p>Der Auswahldialog heißt <em>Ausführung auswählen</em>; ohne Daten erscheint <em>Keine Ausführungen gefunden</em>.</p><div class="tip custom-block"><p class="custom-block-title">Der Editor zeigt echte Werte</p><p>Im Verlaufsmodus sehen Sie an jedem Schritt, was tatsächlich durchgelaufen ist — nicht die Konfiguration. Das ist der schnellste Weg zu verstehen, warum ein Flow sich so verhalten hat.</p></div><h2 id="fehler-nachvollziehen" tabindex="-1">Fehler nachvollziehen <a class="header-anchor" href="#fehler-nachvollziehen" aria-label="Permalink to &quot;Fehler nachvollziehen&quot;">​</a></h2><p>An jedem Schritt:</p><table tabindex="0"><thead><tr><th>Aktion</th><th>Zeigt</th></tr></thead><tbody><tr><td><strong>Details anzeigen</strong></td><td>Ein- und Ausgabedaten des Schritts</td></tr><tr><td><strong>Fehlerdetails anzeigen</strong></td><td>Die Fehlermeldung</td></tr></tbody></table><p>Ein bewährtes Vorgehen:</p><ol><li><strong>Wo bricht es ab?</strong> Die Spalte <em>Schritte</em> zeigt, wie weit der Flow kam.</li><li><strong>Was kam an?</strong> Am letzten erfolgreichen Schritt die Ausgabe prüfen.</li><li><strong>Was wurde erwartet?</strong> Häufig passt ein Format nicht.</li><li><strong>Korrigieren und wiederholen</strong> über <strong>Erneut starten</strong> — gleiche Eingabe, geänderte Konfiguration.</li></ol><h2 id="was-endanwender-sehen" tabindex="-1">Was Endanwender sehen <a class="header-anchor" href="#was-endanwender-sehen" aria-label="Permalink to &quot;Was Endanwender sehen&quot;">​</a></h2><p>Scheitert ein Flow, während jemand eine Seite bearbeitet, erscheint dort:</p><blockquote><p><strong>Dieser Prozessschritt konnte nicht geladen werden</strong></p><p><em>Der aktuelle Schritt konnte aufgrund einer fehlerhaften Konfiguration oder eines ungültigen Werts nicht ausgeführt werden.</em></p><p><em>Bitte wenden Sie sich an den Verantwortlichen für diesen Prozess oder den Administrator Ihrer Organisation.</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">Diese Meldung ist Ihr Stichwort</p><p>Meldet jemand diesen Text, gehen Sie in den Verlauf des betreffenden Flows. Die fehlgeschlagene Ausführung steht dort ganz oben — mit dem Schritt, an dem es scheiterte.</p></div><h2 id="benachrichtigung-bei-fehlern" tabindex="-1">Benachrichtigung bei Fehlern <a class="header-anchor" href="#benachrichtigung-bei-fehlern" aria-label="Permalink to &quot;Benachrichtigung bei Fehlern&quot;">​</a></h2><p>Scheitert eine Ausführung, verschickt ApptiveGrid eine E-Mail. Der Betreff nennt den Flow, der Text enthält Flow-Name, Space-Name und die Fehlermeldung des Schritts, an dem es abbrach.</p><p><strong>Empfänger</strong> sind alle Personen mit der Rolle <strong>Managen</strong> im Space sowie der Eigentümer des Flows.</p><p>Es gibt die Mail in zwei Ausführungen — der Text sagt Ihnen, welcher Fall vorliegt:</p><table tabindex="0"><thead><tr><th>Der Text sagt …</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Ein Fehler ist aufgetreten, prüfen Sie die Details</td><td>Einzelner Fehlschlag, der Flow läuft weiter</td></tr><tr><td><strong>Der Flow wurde gestoppt</strong> und erfordert Ihre Aufmerksamkeit</td><td>Der Flow ist ausgeschaltet und läuft erst nach dem Einschalten wieder</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Dreimal derselbe Fehler schaltet den Flow aus</p><p>Scheitern die letzten drei Ausführungen mit der <strong>identischen</strong> Fehlermeldung, schaltet ApptiveGrid den Flow aus — der <a href="/flows/was-ist-ein-flow#ein-und-ausschalten">Schalter</a> springt auf <em>aus</em>. Danach löst kein Ereignis mehr eine Ausführung aus, bis Sie ihn von Hand wieder einschalten.</p><p>Genau diese Mail ist Ihr Stichwort: Beheben Sie die Ursache, bevor Sie wieder einschalten — sonst sind nach drei weiteren Ereignissen dieselben drei Fehlschläge beisammen und der Flow geht erneut aus.</p><p>Eine erfolgreiche Ausführung oder ein Fehler mit anderer Meldung dazwischen setzt die Zählung zurück. Ein Flow, der jedes zweite Mal scheitert, läuft also weiter — und meldet sich weiter per Mail.</p></div><div class="tip custom-block"><p class="custom-block-title">Wer die Mail nicht bekommt</p><p>Personen mit <strong>Bearbeiten</strong> oder <strong>Ansehen</strong> erhalten keine Fehlermeldung, auch wenn sie am Flow mitgebaut haben. Wer für einen produktiven Flow verantwortlich ist, braucht die Rolle <a href="/zusammenarbeit/rollen">Managen</a> — sonst darf diese Person den Flow anschließend auch nicht wieder einschalten.</p></div><p>Ein überschrittenes Kontingent — etwa die im Tarif enthaltene Zahl an Flow-Schritten — schaltet den Flow sofort aus, ohne die drei Versuche abzuwarten.</p><h2 id="regelmaßig-hineinsehen" tabindex="-1">Regelmäßig hineinsehen <a class="header-anchor" href="#regelmaßig-hineinsehen" aria-label="Permalink to &quot;Regelmäßig hineinsehen&quot;">​</a></h2><p>Sehen Sie bei produktiven Flows trotzdem regelmäßig in den Verlauf — besonders in den ersten Tagen nach einer Änderung. Nicht jeder unerwünschte Verlauf ist ein Fehler: Ein Flow, der zu oft oder mit falschen Werten durchläuft, gilt technisch als erfolgreich und löst keine Mail aus.</p><div class="tip custom-block"><p class="custom-block-title">Zu viele Ausführungen sind auch ein Befund</p><p>Wächst die Liste schneller als erwartet, stimmt meist der Auslöser nicht:</p><ul><li><em>Eintrag wurde geändert</em> ohne Feldbedingung startet bei jeder Kleinigkeit</li><li>Eine Aktion, die in das auslösende Grid schreibt, startet den Flow erneut</li><li>Ein <a href="/grids/csv-import">CSV-Import</a> löst je Zeile einmal aus</li></ul></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/flows/testen">Flows testen</a></li><li><a href="/flows/trigger">Trigger</a></li><li><a href="/fehlerbehebung/haeufige-fehlermeldungen">Häufige Fehlermeldungen</a></li></ul>',39)])])}const f=t(s,[["render",a]]);export{c as __pageData,f as default};
